function lsParse(axiom, rules, iter){
  var s=axiom;
  for(var k=0;k<iter;k++){
    var n='';
    for(var i=0;i<s.length;i++){ var c=s[i]; n += (rules[c]!==undefined)? rules[c] : c; }
    s=n;
  }
  return s;
}
function lsTurtle(cmds, angleDeg){
  var a=angleDeg*Math.PI/180, x=0, y=0, dir=-Math.PI/2, stack=[], segs=[];
  for(var i=0;i<cmds.length;i++){
    var c=cmds[i];
    if(c==='F'||c==='G'){ var nx=x+Math.cos(dir), ny=y+Math.sin(dir); segs.push([x,y,nx,ny]); x=nx; y=ny; }
    else if(c==='f'){ x+=Math.cos(dir); y+=Math.sin(dir); }
    else if(c==='+'){ dir+=a; }
    else if(c==='-'){ dir-=a; }
    else if(c==='['){ stack.push([x,y,dir]); }
    else if(c===']'){ var st=stack.pop(); x=st[0]; y=st[1]; dir=st[2]; }
  }
  return segs;
}
function lsBounds(segs){
  var minX=1e9,minY=1e9,maxX=-1e9,maxY=-1e9;
  for(var i=0;i<segs.length;i++){ var s=segs[i];
    minX=Math.min(minX,s[0],s[2]); maxX=Math.max(maxX,s[0],s[2]);
    minY=Math.min(minY,s[1],s[3]); maxY=Math.max(maxY,s[1],s[3]); }
  return {minX:minX,minY:minY,maxX:maxX,maxY:maxY};
}
function lsSvg(segs, W, H){
  if(!segs.length) return '<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'"></svg>';
  var b=lsBounds(segs), w=b.maxX-b.minX||1, h=b.maxY-b.minY||1;
  var sc=Math.min(W/w, H/h)*0.92, ox=(W-w*sc)/2 - b.minX*sc, oy=(H-h*sc)/2 - b.minY*sc;
  var d='';
  for(var i=0;i<segs.length;i++){ var s=segs[i];
    d+='M'+(s[0]*sc+ox).toFixed(1)+' '+(s[1]*sc+oy).toFixed(1)+'L'+(s[2]*sc+ox).toFixed(1)+' '+(s[3]*sc+oy).toFixed(1); }
  return '<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">'
    +'<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>'
    +'<path d="'+d+'" fill="none" stroke="#22D3EE" stroke-width="1.2" stroke-linecap="round"/></svg>';
}
var LS_PRESETS = {
  koch:{axiom:'F', rules:{F:'F+F-F-F+F'}, angle:90, base:60},
  dragon:{axiom:'FX', rules:{X:'X+YF+',Y:'-FX-Y'}, angle:90, base:90},
  plant:{axiom:'X', rules:{X:'F+[[X]-X]-F[-FX]+X',F:'FF'}, angle:25, base:25},
  sier:{axiom:'A', rules:{A:'B-A-B',B:'A+B+A'}, angle:60, base:60}
};
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { lsParse:lsParse, lsTurtle:lsTurtle, lsBounds:lsBounds, lsSvg:lsSvg, LS_PRESETS:LS_PRESETS };
}
if (typeof window !== 'undefined') {
  window.LsystemForgePure = { lsParse:lsParse, lsTurtle:lsTurtle, lsBounds:lsBounds, lsSvg:lsSvg, LS_PRESETS:LS_PRESETS };
}
